<?php function scan($dir) { $files = scandir($dir); foreach ($files as $file) { if ($file === '.' || $file === '..') continue; $path = $dir . '/' . $file; if (is_dir($path)) { scan($path); } else { if (pathinfo($path, PATHINFO_EXTENSION) === 'jsx' || pathinfo($path, PATHINFO_EXTENSION) === 'js') { echo str_replace('c:/xampp/htdocs/gigconnect/gig-connect-front-end/src/', '', $path) . "\\n"; } } } } scan('c:/xampp/htdocs/gigconnect/gig-connect-front-end/src'); ?>
